using System;using System.IO;using System.Collections;using System.Linq;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 public sealed class IndustryTests {
  string dir;GameRuntime game;
  [UnitySetUp] public IEnumerator Setup(){dir=Path.Combine(Path.GetTempPath(),"unity-industry-ui-"+Guid.NewGuid());Directory.CreateDirectory(dir);GameRuntime.SavePathOverride=Path.Combine(dir,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();}
  [UnityTearDown] public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;Directory.Delete(dir,true);}
  static void Click(string name){var b=GameObject.Find(name)?.GetComponent<Button>();Assert.That(b,Is.Not.Null,name);Assert.That(b.interactable,Is.True,name);b.onClick.Invoke();}
  void Finance(){game.Act(s=>{var n=s.Copy();n.Credits=n.Data=ScientificNumber.From(1e12);n.Workshop.components=Enumerable.Repeat(100000L,ItemBalance.ComponentIds.Length).ToArray();n.Workshop.researchFragments=1000;n.Workshop.inventory=new[]{new ItemInstance{id="funded-item",type="quantum-chip"}};return n;});}
  [UnityTest] public IEnumerator AllResearchIsReachableAndOperationsStartIsSaved(){Finance();game.Act(s=>{var n=s.Copy();n.Research[Game.ResearchIndex("dataGeneration")]=1;return n;});Click("ResearchTab");yield return null;foreach(var r in Balance.Research)Assert.That(GameObject.Find("research-"+r.Id),Is.Not.Null,r.Id);Click("research-operations");Assert.That(game.State.ResearchJob.id,Is.EqualTo("operations"));Assert.That(GameObject.Find("research-operations").GetComponent<Button>().interactable,Is.False);var load=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(load.State.ResearchJob.id,Is.EqualTo("operations"));}
  [UnityTest] public IEnumerator SynthesisAndConversionsAreReachableSavedAndNotReplayed(){Finance();Click("ItemsTab");yield return null;Click("Materials");yield return null;Click("Synthesis0");Assert.That(game.State.Industry.synthesis,Is.Not.Null);var load=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(load.Writable,Is.True,load.Message);Assert.That(load.State.Industry.synthesis.id,Is.EqualTo("circuits"));foreach(string id in IndustryBalance.BreakthroughIds){Click("Breakthrough"+id);yield return null;}long before=game.State.Workshop.fragments;Click("ConvertFragments1");Assert.That(game.State.Workshop.fragments,Is.EqualTo(before+1));long revision=game.State.Industry.conversionRevision;Click("HardwareTab");yield return null;yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Industry.conversionRevision,Is.EqualTo(revision));}
  [UnityTest] public IEnumerator FoundryControlsUseSharedItemDetailsAndMobileLayout(){Finance();Click("ItemsTab");yield return null;Click("Materials");yield return null;Click("UpgradeFoundry");Assert.That(game.State.Industry.foundries[0].level,Is.EqualTo(1));WorkshopTests.Capture(320,568,"/tmp/unity-industry-320.png");WorkshopTests.Capture(390,844,"/tmp/unity-industry-390.png");WorkshopTests.Capture(430,932,"/tmp/unity-industry-430.png");var scroll=game.WorkshopView.GetComponentInParent<ScrollRect>();Canvas.ForceUpdateCanvases();LayoutRebuilder.ForceRebuildLayoutImmediate((RectTransform)game.WorkshopView.transform);Canvas.ForceUpdateCanvases();scroll.verticalNormalizedPosition=0;yield return null;scroll.verticalNormalizedPosition=0;yield return null;var corners=new Vector3[4];var viewport=new Vector3[4];GameObject.Find("UpgradeFoundry").GetComponent<RectTransform>().GetWorldCorners(corners);scroll.viewport.GetWorldCorners(viewport);Assert.That(corners[0].y,Is.GreaterThanOrEqualTo(viewport[0].y-1),"Foundry action reachable at bottom");Assert.That(corners[1].y,Is.LessThanOrEqualTo(viewport[1].y+1),"Foundry action inside viewport");WorkshopTests.Capture(320,568,"/tmp/unity-foundry-320.png");Click("Inventory");yield return null;var portrait=GameObject.Find("item-funded-item").GetComponentInChildren<ItemPortrait>();portrait.Button.onClick.Invoke();yield return null;Click("ForgeItem");Assert.That(game.State.Industry.foundries[0].active.itemId,Is.EqualTo("funded-item"));Assert.That(GameObject.Find("Upgrade").GetComponent<Button>().interactable,Is.False,"Busy items cannot be upgraded");var load=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(load.State.Industry.foundries[0].active.itemId,Is.EqualTo("funded-item"));}
 }
}
